SELECT p.id as p_id, p.name as p_name, p.price as p_price, p.category_id as p_category_id, p.status as p_status,
       c.id as c_id, c.name as c_name, c.description as c_description
FROM product p
LEFT JOIN category c ON p.category_id = c.id


        AND p.name LIKE CONCAT('%', #{name}, '%')


        AND p.price >= #{minPrice}


        AND p.price <= #{maxPrice}


        AND p.status IN

            #{item}

mapper.update:
UPDATE product

    name = #{name},
    price = #{price},
    category_id = #{categoryId},
    status = #{status, typeHandler=com.example.mybatis.handler.ProductStatusTypeHandler}

WHERE id = #{id}
